class MinStack:
    """A stack that reports its smallest value.

    Each entry in ``_items`` has a matching entry in ``_mins`` holding the
    minimum of all values at or below it. This keeps push, pop, top and
    get_min at constant time, and pop restores the previous minimum.
    Equal values are kept as separate entries, so duplicates are handled.
    """

    def __init__(self):
        self._items = []
        self._mins = []

    def push(self, value):
        if self._mins:
            current_min = self._mins[-1]
            new_min = value if value < current_min else current_min
        else:
            new_min = value
        self._items.append(value)
        self._mins.append(new_min)

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty MinStack")
        self._mins.pop()
        return self._items.pop()

    def top(self):
        if not self._items:
            raise IndexError("top from empty MinStack")
        return self._items[-1]

    def get_min(self):
        if not self._mins:
            raise ValueError("get_min from empty MinStack")
        return self._mins[-1]

    def __len__(self):
        return len(self._items)
